import Link from 'next/link'
import { FaCalendar, FaEye, FaPlay } from 'react-icons/fa'

interface NewsItem {
  id: string
  title: string
  content: string
  category: string
  image: string
  slug: string
  views: number
  video_url?: string
  video_type?: string
  description?: string
  created_at: string
}

// دالة آمنة لاستخراج YouTube ID
function getYouTubeId(url: string | undefined): string {
  if (!url) return ''
  const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/
  const match = url.match(regExp)
  return (match && match[2].length === 11) ? match[2] : ''
}

export default function NewsCard({ news }: { news: NewsItem }) {
  const date = new Date(news.created_at).toLocaleDateString('ar-EG')
  
  // التحقق من وجود فيديو
  const hasVideo = news.video_url && news.video_url !== '' && news.video_type !== 'none'

  return (
    <Link href={`/news/${news.slug}`}>
      <div className="bg-white dark:bg-cardBg rounded-xl overflow-hidden shadow-lg card-hover cursor-pointer border border-gray-200 dark:border-gray-800 h-full flex flex-col transition-all duration-300 hover:shadow-2xl">
        
        <div className="relative group overflow-hidden bg-gray-900">
          {/* إذا كان فيديو مرفوع، نعرض الفيديو مباشرة مع mute */}
          {hasVideo && news.video_type === 'upload' ? (
            <video 
              src={news.video_url}
              className="w-full h-56 object-cover group-hover:scale-105 transition-transform duration-500"
              autoPlay
              loop
              muted
              playsInline
              preload="metadata"
            />
          ) : hasVideo && news.video_type === 'youtube' && news.video_url ? (
            // معاينة من YouTube (مع التحقق من وجود الرابط)
            <img 
              src={`https://img.youtube.com/vi/${getYouTubeId(news.video_url)}/mqdefault.jpg`}
              alt={news.title}
              className="w-full h-56 object-cover group-hover:scale-105 transition-transform duration-500"
              onError={(e) => {
                e.currentTarget.src = news.image || 'https://placehold.co/600x400/1a1a1a/ffffff?text=No+Image'
              }}
            />
          ) : (
            <img 
              src={news.image || 'https://placehold.co/600x400/1a1a1a/ffffff?text=No+Image'} 
              alt={news.title} 
              className="w-full h-56 object-cover group-hover:scale-105 transition-transform duration-500"
            />
          )}
          
          {/* زر التشغيل (يظهر عند التمرير) */}
          {hasVideo && (
            <>
              <div className="absolute inset-0 bg-black/30 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                <div className="w-14 h-14 bg-red-600 rounded-full flex items-center justify-center hover:scale-110 transition-transform shadow-xl">
                  <FaPlay className="text-white text-xl ml-0.5" />
                </div>
              </div>
              
              {/* شارة فيديو */}
              <div className="absolute top-3 right-3 bg-red-600 text-white text-xs px-2.5 py-1 rounded-full flex items-center gap-1 shadow-lg font-bold z-10">
                <FaPlay size={10} /> فيديو
              </div>
            </>
          )}
        </div>
        
        <div className="p-5 flex-1 flex flex-col">
          <span className="text-red-600 text-xs font-bold uppercase tracking-wider">
            {news.category || 'عام'}
          </span>
          <h2 className="text-xl font-bold mt-2 line-clamp-2 group-hover:text-red-600 transition-colors">
            {news.title}
          </h2>
          <p className="text-gray-600 dark:text-gray-400 mt-3 line-clamp-3 flex-1">
            {news.description || news.content?.substring(0, 120)}
          </p>
          <div className="flex justify-between items-center mt-4 pt-2 text-sm text-gray-500 border-t border-gray-100 dark:border-gray-800">
            <span className="flex items-center gap-1">
              <FaCalendar size={12} /> {date}
            </span>
            <span className="flex items-center gap-1">
              <FaEye size={12} /> {news.views || 0}
            </span>
          </div>
        </div>
      </div>
    </Link>
  )
}